// Development-only driver calls actual unexported source methods. The stager
// redirects wall clock reads only; estimator arithmetic is never copied here.
package gcc
import("bufio";"encoding/json";"os";"runtime";"testing";"time";"github.com/pion/interceptor/internal/cc";"github.com/pion/logging")
var sourceOracleClock=time.Unix(1000,0)
func oracleNow()time.Time{return sourceOracleClock}
func oracleSince(at time.Time)time.Duration{return sourceOracleClock.Sub(at)}
type sourceEvent struct{AtNS int64 `json:"at_ns"`;MeasurementNS int64 `json:"measurement_ns"`;EstimateNS int64 `json:"estimate_ns"`;ReceiveDeltaNS int64 `json:"receive_delta_ns"`;Usage int `json:"usage"`;Received int `json:"received"`;RTTNS int64 `json:"rtt_ns"`;Wanted int `json:"wanted"`;DepartureNS *int64 `json:"departure_ns"`;ArrivalNS *int64 `json:"arrival_ns"`;Size int `json:"size"`;Lost,Total int}
type sourceCase struct{Name string `json:"name"`;Stage string `json:"stage"`;Events []sourceEvent `json:"events"`}
func TestSourceOracle(t *testing.T){input:=os.Getenv("PION_GCC_SOURCE_INPUT");output:=os.Getenv("PION_GCC_SOURCE_OUTPUT");if input==""||output==""{t.Fatal("explicit owned input/output required")};f,err:=os.Open(input);if err!=nil{t.Fatal(err)};defer f.Close();o,err:=os.Create(output);if err!=nil{t.Fatal(err)};defer o.Close();enc:=json.NewEncoder(o);scan:=bufio.NewScanner(f);scan.Buffer(make([]byte,4096),4*1024*1024);for scan.Scan(){var c sourceCase;if err:=json.Unmarshal(scan.Bytes(),&c);err!=nil{t.Fatal(err)};sourceOracleClock=time.Unix(1000,0);k:=newKalman();threshold:=newAdaptiveThreshold();var delay []DelayStats;rate:=newRateController(oracleNow,1_000_000,5_000,50_000_000,func(s DelayStats){delay=append(delay,s)});loss:=newLossBasedBWE(1_000_000,logging.NewDefaultLoggerFactory());overuse:=newOveruseDetector(newAdaptiveThreshold(),10*time.Millisecond,func(s DelayStats){delay=append(delay,s)});acks:=[]cc.Acknowledgment{};for i,e:=range c.Events{sourceOracleClock=time.Unix(1000,e.AtNS);row:=map[string]any{"case":c.Name,"stage":c.Stage,"index":i,"goos":runtime.GOOS,"goarch":runtime.GOARCH};switch c.Stage{case "kalman":row["estimate_ns"]=int64(k.updateEstimate(time.Duration(e.MeasurementNS)));row["error"]=k.estimateError;row["uncertainty"]=k.measurementUncertainty;row["gain"]=k.gain
case "threshold":u,s,th:=threshold.compare(time.Duration(e.EstimateNS),time.Duration(e.ReceiveDeltaNS));row["usage"]=int(u);row["estimate_ns"]=int64(s);row["threshold_ns"]=int64(th);row["next_threshold_ns"]=int64(threshold.thresh)
case "overuse":overuse.onDelayStats(DelayStats{Measurement:time.Duration(e.MeasurementNS),Estimate:time.Duration(e.EstimateNS),LastReceiveDelta:time.Duration(e.ReceiveDeltaNS)});row["stats"]=delay[len(delay)-1];row["count"]=overuse.increasingCounter;row["increasing_ns"]=int64(overuse.increasingDuration)
case "rate":rate.onReceivedRate(e.Received);rate.updateRTT(time.Duration(e.RTTNS));before:=len(delay);rate.onDelayStats(DelayStats{Measurement:time.Duration(e.MeasurementNS),Estimate:time.Duration(e.EstimateNS),LastReceiveDelta:time.Duration(e.ReceiveDeltaNS),Usage:usage(e.Usage)});row["emitted"]=len(delay)>before;row["target"]=rate.target;row["stored_stats"]=rate.delayStats;if len(delay)>before{row["stats"]=delay[len(delay)-1]}
case "loss":batch:=make([]cc.Acknowledgment,e.Total);for j:=range batch{if j>=e.Lost{batch[j].Arrival=sourceOracleClock}};loss.updateLossEstimate(batch);row["stats"]=loss.getEstimate(e.Wanted);row["bitrate"]=loss.bitrate
case "groups","received":a:=cc.Acknowledgment{Size:e.Size};if e.DepartureNS!=nil{a.Departure=time.Unix(1000,*e.DepartureNS)};if e.ArrivalNS!=nil{a.Arrival=time.Unix(1000,*e.ArrivalNS)};acks=append(acks,a);if i+1!=len(c.Events){continue};ch:=make(chan []cc.Acknowledgment,1);ch<-acks;close(ch);if c.Stage=="groups"{groups:=[]map[string]int64{};newArrivalGroupAccumulator().run(ch,func(g arrivalGroup){groups=append(groups,map[string]int64{"departure_ns":g.departure.Sub(time.Unix(1000,0)).Nanoseconds(),"arrival_ns":g.arrival.Sub(time.Unix(1000,0)).Nanoseconds(),"packets":int64(len(g.packets))})});row["groups"]=groups}else{rates:=[]int{};newRateCalculator(500*time.Millisecond).run(ch,func(v int){rates=append(rates,v)});row["rates"]=rates}
default:t.Fatalf("unknown stage %s",c.Stage)};if err:=enc.Encode(row);err!=nil{t.Fatal(err)}}};if err:=scan.Err();err!=nil{t.Fatal(err)}}
